window.SEG=[{"i": 0, "a": 0.25, "b": 0.948, "text": "«أنا سالم.»"}, {"i": 1, "a": 1.278, "b": 2.48, "text": "الصوت جاي من تحت…"}, {"i": 2, "a": 3.06, "b": 4.934, "text": "من ظل صغير قاعد عند البسطة."}, {"i": 3, "a": 5.264, "b": 7.81, "text": "طالعت جوالي… رسالة سالم للحين قدامي."}, {"i": 4, "a": 8.14, "b": 9.93, "text": "وتحت… ولد يقول إنه هو سالم."}, {"i": 5, "a": 10.26, "b": 11.546, "text": "اثنين بنفس الاسم…"}, {"i": 6, "a": 12.126, "b": 13.328, "text": "وواحد منهم يكذب."}, {"i": 7, "a": 13.658, "b": 14.86, "text": "قال الولد بهدوء:"}, {"i": 8, "a": 15.19, "b": 17.232, "text": "«يوم الحريق… كنا مع بعض يا نواف."}, {"i": 9, "a": 17.562, "b": 18.512, "text": "وأنت… تركتني.»"}, {"i": 10, "a": 18.842, "b": 19.96, "text": "رجعت خطوة لورا…"}, {"i": 11, "a": 20.54, "b": 21.994, "text": "وفجأة… جاني صداع قوي."}, {"i": 12, "a": 22.324, "b": 23.778, "text": "كأن شي ينفتح في راسي."}, {"i": 13, "a": 24.108, "b": 26.234, "text": "شفت نفسي صغير… أركض في ممر مظلم…"}, {"i": 14, "a": 26.814, "b": 27.68, "text": "ماسك يد ولد…"}, {"i": 15, "a": 28.26, "b": 29.21, "text": "والولد يصرخ:"}, {"i": 16, "a": 29.54, "b": 30.826, "text": "«لا تتركني يا نواف!»"}, {"i": 17, "a": 31.756, "b": 32.958, "text": "وانقطعت الذكرى."}, {"i": 18, "a": 33.288, "b": 34.994, "text": "رجعت للدرج… أتنفس بسرعة."}, {"i": 19, "a": 35.324, "b": 36.358, "text": "قلت له: «كم عمرك؟»"}, {"i": 20, "a": 36.688, "b": 37.638, "text": "قال: «خمسة عشر.»"}, {"i": 21, "a": 37.968, "b": 39.674, "text": "وقبل ما أنزل… جوالي اهتز."}, {"i": 22, "a": 40.004, "b": 41.122, "text": "رسالة فيها ملف:"}, {"i": 23, "a": 42.252, "b": 43.454, "text": "«تقرير وفاة سالم.»"}, {"i": 24, "a": 44.184, "b": 44.714, "text": "فتحته…"}, {"i": 25, "a": 45.294, "b": 46.916, "text": "صورة شاب… ما يشبهني أبد."}, {"i": 26, "a": 47.246, "b": 48.028, "text": "«سالم ناصر."}, {"i": 27, "a": 48.758, "b": 51.22, "text": "العمر عند الوفاة: اثنين وعشرين سنة."}, {"i": 28, "a": 51.95, "b": 54.58, "text": "تاريخ الوفاة: قبل الحريق بثلاثة أيام.»"}, {"i": 29, "a": 55.71, "b": 57.668, "text": "سالم كان عمره اثنين وعشرين…"}, {"i": 30, "a": 58.248, "b": 60.374, "text": "والولد اللي تحت يقول خمسة عشر."}, {"i": 31, "a": 60.704, "b": 62.662, "text": "وسالم مات… قبل الحريق أصلًا!"}, {"i": 32, "a": 63.592, "b": 64.626, "text": "رجعت عن الدرج…"}, {"i": 33, "a": 65.206, "b": 67.5, "text": "وفتحت الرسالة الصوتية الثانية:"}, {"i": 34, "a": 67.83, "b": 70.292, "text": "«نواف… أنا مت قبل الحريق بثلاثة أيام!"}, {"i": 35, "a": 70.622, "b": 71.74, "text": "اللي تحت… مو أنا.»"}, {"i": 36, "a": 73.07, "b": 74.104, "text": "وسكت التسجيل."}, {"i": 37, "a": 75.234, "b": 76.52, "text": "وبعدها… سمعت ضحكة."}, {"i": 38, "a": 76.85, "b": 77.968, "text": "ضحكة ولد… من تحت."}, {"i": 39, "a": 78.298, "b": 79.416, "text": "وقال بصوت هادي:"}, {"i": 40, "a": 79.746, "b": 80.78, "text": "«صح… أنا مو سالم."}, {"i": 41, "a": 81.11, "b": 82.9, "text": "وأنت ما تركت سالم يا نواف…"}, {"i": 42, "a": 83.48, "b": 84.514, "text": "أنت تركت نفسك.»"}, {"i": 43, "a": 84.844, "b": 86.046, "text": "وبدا يطلع الدرج."}, {"i": 44, "a": 87.176, "b": 88.966, "text": "أول شي… شفت ظله على الجدار."}, {"i": 45, "a": 89.296, "b": 90.246, "text": "بعدين رجوله…"}, {"i": 46, "a": 91.226, "b": 93.016, "text": "بعدين يده… على الدرابزين."}, {"i": 47, "a": 93.746, "b": 94.192, "text": "خطوة…"}, {"i": 48, "a": 95.572, "b": 96.018, "text": "خطوة…"}, {"i": 49, "a": 97.398, "b": 98.432, "text": "لين وصل للنور."}, {"i": 50, "a": 99.762, "b": 100.544, "text": "ورفع وجهه."}, {"i": 51, "a": 102.274, "b": 103.728, "text": "وتجمد الدم في عروقي."}, {"i": 52, "a": 104.658, "b": 105.692, "text": "الولد… كان أنا."}, {"i": 53, "a": 107.422, "b": 109.296, "text": "أنا… وأنا عمري خمسة عشر سنة."}, {"i": 54, "a": 110.226, "b": 111.092, "text": "ابتسم وقال:"}, {"i": 55, "a": 111.422, "b": 112.54, "text": "«تذكرني يا نواف؟"}, {"i": 56, "a": 112.87, "b": 114.156, "text": "أنا اللي بقيت تحت…"}, {"i": 57, "a": 114.736, "b": 116.274, "text": "وأنت اللي طلعت مكاني!»"}, {"i": 58, "a": 117.204, "b": 118.49, "text": "وجوالي اهتز فجأة:"}, {"i": 59, "a": 118.82, "b": 119.518, "text": "«لا تلمسه!"}, {"i": 60, "a": 120.248, "b": 121.786, "text": "إذا لمسك… بتتذكر كل شي!»"}, {"i": 61, "a": 122.716, "b": 123.498, "text": "ومد يده لي…"}, {"i": 62, "a": 125.078, "b": 125.944, "text": "ورجعت لورا…"}, {"i": 63, "a": 127.524, "b": 128.894, "text": "والحين أبي أسألكم…"}, {"i": 64, "a": 129.474, "b": 130.592, "text": "لو كنتوا مكاني…"}, {"i": 65, "a": 131.172, "b": 133.298, "text": "بتقربون منه وتعرفون الحقيقة؟"}, {"i": 66, "a": 133.628, "b": 135.418, "text": "ولا تهربون قبل ما يلمسكم؟"}];
